// =========================================================================
// SHAYMIN - NHÍM HOA CỎ GRACIDEA - Modern HTML5 Canvas 2D Implementation
// 3D Pop Mart / Vinyl Toy Aesthetic with Organic Micro-Physics
// =========================================================================
function drawShayminFloraHedgehog(ctx, cx, cy, scale, t) {
  ctx.save();
  // 1. Nhịp thở Squash & Stretch 5%
  const breathFreq = 2.1;
  const breathPhase = t * breathFreq;
  const breathSin = Math.sin(breathPhase);
  const by = cy + breathSin * 2.5;
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;

  ctx.translate(cx, by);
  ctx.scale(scale, scale);

  // Trễ pha vi vật lý hữu cơ
  const petalLag = breathPhase - 0.25; // 80ms lag (~0.25 rad)
  const petalFlutter = Math.sin(petalLag) * 2.2;
  const footLag = breathPhase - 0.40;
  const footWobble = Math.sin(footLag) * 1.5;

  // Chớp mắt tự nhiên 3.5s (duration 140ms)
  const blink = (Math.sin(t * 1.8) > 0.95);

  // 2. Bóng tiếp xúc mặt sàn co giãn êm ái (Ground contact shadow)
  ctx.save();
  const shadowW = 50 * (1.0 + 0.04 * breathSin);
  const shadowH = 10 * (1.0 - 0.03 * breathSin);
  const shadowGrad = ctx.createRadialGradient(8, 42 - breathSin * 2.5, 3, 8, 42 - breathSin * 2.5, shadowW);
  shadowGrad.addColorStop(0, "rgba(15, 23, 42, 0.45)");
  shadowGrad.addColorStop(0.5, "rgba(30, 41, 59, 0.22)");
  shadowGrad.addColorStop(1, "rgba(100, 116, 139, 0)");
  ctx.fillStyle = shadowGrad;
  ctx.beginPath();
  ctx.ellipse(8, 42 - breathSin * 2.5, shadowW, shadowH, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 3. Chân sau và trước bên phải (lớp khuất trong bóng)
  ctx.save();
  ctx.fillStyle = "#CBD5E1";
  ctx.beginPath();
  ctx.roundRect(30, 22 + footWobble * 0.4, 14 * sX, 18 * sY, 6);
  ctx.fill();
  ctx.beginPath();
  ctx.roundRect(-6, 23 + footWobble * 0.4, 12 * sX, 18 * sY, 6);
  ctx.fill();
  ctx.restore();

  // 4. Lớp gai cỏ sâu phía sau lưng (3D Back Spikes Layer 1)
  ctx.save();
  ctx.fillStyle = "#365314";
  ctx.beginPath();
  const backSpikes = [
    [6, -38, 18, -56, 28, -36],
    [24, -36, 38, -52, 46, -30],
    [40, -30, 58, -42, 60, -20],
    [52, -20, 72, -26, 66, -8],
    [58, -8, 76, 0, 62, 14],
    [52, 8, 68, 18, 50, 26]
  ];
  for (let sp of backSpikes) {
    ctx.moveTo(sp[0], sp[1]);
    ctx.lineTo(sp[2], sp[3]);
    ctx.lineTo(sp[4], sp[5]);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // 5. Cánh hoa Gracidea tai phải (xa)
  ctx.save();
  ctx.fillStyle = "#BE185D";
  ctx.beginPath();
  ctx.arc(-18 + petalFlutter, -22, 8, 0, Math.PI * 2);
  ctx.arc(-10 + petalFlutter, -28, 7, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#F472B6";
  ctx.beginPath();
  ctx.arc(-18 + petalFlutter, -22, 6, 0, Math.PI * 2);
  ctx.arc(-10 + petalFlutter, -28, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 6. Lớp gai cỏ trung gian 3D (Layer 2)
  ctx.save();
  ctx.fillStyle = "#4D7C0F";
  ctx.beginPath();
  const midSpikes = [
    [0, -32, 10, -50, 22, -30],
    [18, -30, 30, -46, 38, -24],
    [32, -24, 48, -36, 50, -14],
    [44, -14, 60, -18, 54, 2],
    [48, 0, 62, 8, 48, 20]
  ];
  for (let sp of midSpikes) {
    ctx.moveTo(sp[0], sp[1]);
    ctx.lineTo(sp[2], sp[3]);
    ctx.lineTo(sp[4], sp[5]);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // 7. Khối lưng cỏ xanh ngọc mướt mát (Lush Jade Grass Torso Dome)
  ctx.save();
  const grassGrad = ctx.createRadialGradient(10, -16, 8, 16, -6, 56);
  grassGrad.addColorStop(0, "#A3E635"); // Đỉnh ngọc non đón sáng
  grassGrad.addColorStop(0.5, "#65A30D"); // Xanh ngọc mướt mát
  grassGrad.addColorStop(1, "#4D7C0F"); // Đổ bóng khối cầu
  ctx.fillStyle = grassGrad;
  ctx.beginPath();
  ctx.ellipse(16, -6, 46 * sX, 34 * sY, 0, 0, Math.PI * 2);
  ctx.fill();

  // Vòm gai cỏ che trán
  ctx.fillStyle = "#65A30D";
  ctx.beginPath();
  const frontSpikes = [
    [-30, -16, -22, -34, -12, -18],
    [-18, -20, -10, -40, 2, -20],
    [-4, -22, 6, -44, 16, -20],
    [10, -20, 22, -38, 30, -18]
  ];
  for (let sp of frontSpikes) {
    ctx.moveTo(sp[0], sp[1]);
    ctx.lineTo(sp[2], sp[3]);
    ctx.lineTo(sp[4], sp[5]);
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // 8. Đốm phấn hoa vàng hoàng kim trên lưng cỏ
  ctx.save();
  const pollens = [
    [-16, -22, 5, 3, 0.3],
    [8, -28, 6, 4, 0.4],
    [32, -12, 5, 3, -0.2],
    [24, 2, 4, 2, 0.1]
  ];
  for (let p of pollens) {
    ctx.fillStyle = "#FACC15";
    ctx.beginPath();
    ctx.ellipse(p[0], p[1], p[2], p[3], p[4], 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#FEF08A";
    ctx.beginPath();
    ctx.arc(p[0], p[1], p[3] * 0.45, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // 9. Thân trắng muốt bồng bềnh (Porcelain Body Torso)
  ctx.save();
  const bodyGrad = ctx.createRadialGradient(4, 12, 6, 6, 16, 40);
  bodyGrad.addColorStop(0, "#FFFFFF");
  bodyGrad.addColorStop(0.75, "#F8FAFC");
  bodyGrad.addColorStop(1, "#E2E8F0");
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(6, 16, 36 * sX, 22 * sY, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 10. Chân nhỏ tròn vo như hạt đậu (Foreground Bean Feet)
  ctx.save();
  // Chân trước trái
  const f1x = -24, f1y = 20 + footWobble;
  ctx.fillStyle = "#FFFFFF";
  ctx.strokeStyle = "#E2E8F0";
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.roundRect(f1x, f1y, 16 * sX, 20 * sY, 7);
  ctx.fill();
  ctx.stroke();
  // Kẽ ngón chân
  ctx.strokeStyle = "#CBD5E1";
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(f1x + 5, f1y + 13); ctx.lineTo(f1x + 5, f1y + 18);
  ctx.moveTo(f1x + 10, f1y + 13); ctx.lineTo(f1x + 10, f1y + 18);
  ctx.stroke();

  // Chân sau trái
  const f2x = 18, f2y = 20 - footWobble;
  ctx.fillStyle = "#FFFFFF";
  ctx.strokeStyle = "#E2E8F0";
  ctx.beginPath();
  ctx.roundRect(f2x, f2y, 17 * sX, 20 * sY, 7);
  ctx.fill();
  ctx.stroke();
  ctx.strokeStyle = "#CBD5E1";
  ctx.beginPath();
  ctx.moveTo(f2x + 5, f2y + 13); ctx.lineTo(f2x + 5, f2y + 18);
  ctx.moveTo(f2x + 11, f2y + 13); ctx.lineTo(f2x + 11, f2y + 18);
  ctx.stroke();
  ctx.restore();

  // 11. Đầu trắng muốt & Sống mũi nhô ra thanh tú (Head & Snout)
  ctx.save();
  const hx = -34, hy = 4;
  const headGrad = ctx.createRadialGradient(hx - 2, hy - 2, 4, hx, hy, 28);
  headGrad.addColorStop(0, "#FFFFFF");
  headGrad.addColorStop(0.75, "#F8FAFC");
  headGrad.addColorStop(1, "#E2E8F0");
  ctx.fillStyle = headGrad;
  ctx.beginPath();
  ctx.ellipse(hx, hy, 26 * sX, 22 * sY, 0, 0, Math.PI * 2);
  ctx.fill();

  // Mõm nhô ra sang trái
  ctx.beginPath();
  ctx.moveTo(hx - 14, hy - 6);
  ctx.lineTo(hx - 28, hy + 2);
  ctx.lineTo(hx - 12, hy + 10);
  ctx.closePath();
  ctx.fill();

  // Má ửng hồng cam tự nhiên
  const blushGrad = ctx.createRadialGradient(hx - 2, hy + 9, 1, hx - 2, hy + 9, 8);
  blushGrad.addColorStop(0, "rgba(251, 146, 60, 0.75)");
  blushGrad.addColorStop(1, "rgba(251, 146, 60, 0)");
  ctx.fillStyle = blushGrad;
  ctx.beginPath();
  ctx.ellipse(hx - 2, hy + 9, 8, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Miệng cười hé mở ngọt ngào
  ctx.fillStyle = "#9F1239";
  ctx.beginPath();
  ctx.moveTo(hx - 20, hy + 6);
  ctx.lineTo(hx - 12, hy + 5);
  ctx.lineTo(hx - 14, hy + 14);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#FDA4AF";
  ctx.beginPath();
  ctx.arc(hx - 14, hy + 10, 4, 0, Math.PI * 2);
  ctx.fill();

  // Sống mũi nhỏ cúc áo
  ctx.fillStyle = "#0F172A";
  ctx.beginPath();
  ctx.arc(hx - 28, hy + 2, 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath();
  ctx.arc(hx - 29, hy + 1, 1, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // 12. Hai chiếc lá xanh mướt nâng đỡ đài hoa Gracidea
  ctx.save();
  const flx = -14, fly = 6;
  // Lá chúc xuống
  const leaf1Grad = ctx.createLinearGradient(flx, fly, flx - 4, fly + 32);
  leaf1Grad.addColorStop(0, "#4ADE80");
  leaf1Grad.addColorStop(1, "#14532D");
  ctx.fillStyle = leaf1Grad;
  ctx.beginPath();
  ctx.moveTo(flx, fly + 6);
  ctx.lineTo(flx - 4, fly + 32);
  ctx.lineTo(flx + 16, fly + 20);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "#86EFAC";
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(flx + 3, fly + 8); ctx.lineTo(flx + 4, fly + 25);
  ctx.stroke();

  // Lá vươn sang sườn phải
  const leaf2Grad = ctx.createLinearGradient(flx, fly, flx + 36, fly + 14);
  leaf2Grad.addColorStop(0, "#4ADE80");
  leaf2Grad.addColorStop(1, "#14532D");
  ctx.fillStyle = leaf2Grad;
  ctx.beginPath();
  ctx.moveTo(flx + 8, fly);
  ctx.lineTo(flx + 36, fly + 14);
  ctx.lineTo(flx + 16, fly + 24);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(flx + 11, fly + 2); ctx.lineTo(flx + 25, fly + 14);
  ctx.stroke();
  ctx.restore();

  // 13. ĐÓA HOA HỒNG GRACIDEA NỞ RỘ (6 CÁNH LỚN BUNG NỞ)
  ctx.save();
  const petalAngles = [0, 1.047, 2.094, 3.141, 4.188, 5.235];
  const petalLens = [24, 26, 25, 23, 22, 25];

  for (let p = 0; p < 6; p++) {
    const ang = petalAngles[p] + 0.18 + petalFlutter * 0.03;
    const cosA = Math.cos(ang);
    const sinA = Math.sin(ang);
    const len = petalLens[p];

    const tipX = flx + cosA * len;
    const tipY = fly + sinA * len;

    const perpCos = -sinA;
    const perpSin = cosA;
    const w = 9;
    const b1x = flx + cosA * 6 + perpCos * w;
    const b1y = fly + sinA * 6 + perpSin * w;
    const b2x = flx + cosA * 6 - perpCos * w;
    const b2y = fly + sinA * 6 - perpSin * w;

    const petalGrad = ctx.createLinearGradient(flx, fly, tipX, tipY);
    petalGrad.addColorStop(0, "#BE185D");
    petalGrad.addColorStop(0.45, "#F472B6");
    petalGrad.addColorStop(1, "#FCE7F3");
    ctx.fillStyle = petalGrad;

    ctx.beginPath();
    ctx.moveTo(flx, fly);
    ctx.quadraticCurveTo(b1x, b1y, tipX, tipY);
    ctx.quadraticCurveTo(b2x, b2y, flx, fly);
    ctx.fill();
    ctx.strokeStyle = "rgba(253, 242, 248, 0.7)";
    ctx.lineWidth = 1.0;
    ctx.stroke();
  }

  // Tâm đài hoa hồng đậm
  ctx.fillStyle = "#BE185D";
  ctx.beginPath();
  ctx.arc(flx, fly, 8, 0, Math.PI * 2);
  ctx.fill();

  // Nhị hoa vàng hoàng kim tỏa hương
  ctx.fillStyle = "#F59E0B";
  ctx.beginPath();
  ctx.arc(flx, fly, 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#FEF08A";
  ctx.beginPath();
  ctx.arc(flx - 0.5, fly - 0.5, 1.5, 0, Math.PI * 2);
  ctx.fill();

  // Hạt nhụy hoa tím thẫm
  ctx.fillStyle = "#4A044E";
  for (let s = 0; s < 6; s++) {
    const ang = petalAngles[s] + 0.18;
    const sx = flx + Math.cos(ang) * 7.0;
    const sy = fly + Math.sin(ang) * 7.0;
    ctx.beginPath();
    ctx.arc(sx, sy, 1.4, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // 14. ĐÔI MẮT PHA LÊ XANH LỤC BẢO (3-Point Specular Emerald Crystal Eyes)
  ctx.save();
  const ex = hx - 12, ey = hy - 3;

  if (blink) {
    ctx.strokeStyle = "#052E16";
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.arc(ex, ey + 3, 6, 0.2, Math.PI - 0.2);
    ctx.stroke();
  } else {
    // Hốc mắt lục bảo sâu
    ctx.fillStyle = "#052E16";
    ctx.beginPath();
    ctx.ellipse(ex, ey, 7, 10, 0, 0, Math.PI * 2);
    ctx.fill();

    // Mống mắt ngọc lục bảo
    const eyeGrad = ctx.createLinearGradient(ex, ey - 8, ex, ey + 10);
    eyeGrad.addColorStop(0, "#065F46");
    eyeGrad.addColorStop(0.5, "#10B981");
    eyeGrad.addColorStop(1, "#34D399");
    ctx.fillStyle = eyeGrad;
    ctx.beginPath();
    ctx.ellipse(ex, ey + 2, 6, 7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Vòm sáng đáy mắt
    ctx.fillStyle = "#6EE7B7";
    ctx.beginPath();
    ctx.ellipse(ex, ey + 5, 4, 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Đồng tử đen thẫm
    ctx.fillStyle = "#052E16";
    ctx.beginPath();
    ctx.arc(ex, ey - 2, 4, 0, Math.PI * 2);
    ctx.fill();

    // 3 Điểm sáng pha lê
    ctx.fillStyle = "#FFFFFF";
    // Điểm 1: Primary Direct Keylight
    ctx.beginPath(); ctx.arc(ex - 2, ey - 4, 2.4, 0, Math.PI * 2); ctx.fill();
    // Điểm 2: Secondary Emerald Caustic Bounce
    ctx.beginPath(); ctx.arc(ex + 2, ey + 4, 1.4, 0, Math.PI * 2); ctx.fill();
    // Điểm 3: Tertiary Surface Wetness Sparkle
    ctx.beginPath(); ctx.arc(ex + 2, ey - 2, 0.9, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  ctx.restore();
}
